migrations.sql:
PRAGMA foreign_keys=ON;
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE memberships(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),roles_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),token_hash TEXT NOT NULL UNIQUE,csrf_token TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE bootstrap_lock(id INTEGER PRIMARY KEY CHECK(id=1));
CREATE TABLE audit_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE connections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider TEXT NOT NULL,name TEXT NOT NULL,config_json TEXT NOT NULL,secret_ciphertext TEXT,status TEXT NOT NULL DEFAULT 'unverified',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE workspace_settings(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),settings_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX audit_workspace ON audit_events(workspace_id,created_at);
CREATE TABLE login_limits(identity_hash TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window_start INTEGER NOT NULL);

CREATE TABLE platform_scheduler_leases (
  name TEXT PRIMARY KEY,
  holder TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE platform_scheduler_runs (
  id TEXT PRIMARY KEY,
  lane TEXT NOT NULL,
  workspace_id TEXT,
  state TEXT NOT NULL,
  started_at TEXT NOT NULL,
  finished_at TEXT,
  error_code TEXT
);
CREATE INDEX platform_scheduler_history ON platform_scheduler_runs(workspace_id, started_at);

CREATE TABLE connection_validations(workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_revision INTEGER NOT NULL,validated_at TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(workspace_id,connection_id));
CREATE TABLE connection_snapshots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL,cursor_json TEXT NOT NULL,gaps_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,name TEXT NOT NULL,facts_json TEXT NOT NULL,UNIQUE(snapshot_id,kind,source_id));
CREATE TABLE connection_adoptions(workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,target_id TEXT,reviewed_name TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(workspace_id,connection_id,kind,source_id));

CREATE TABLE work_records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,requester_id TEXT NOT NULL,beneficiary_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',sensitivity TEXT NOT NULL DEFAULT 'normal',assignee_id TEXT,impact TEXT NOT NULL DEFAULT 'individual',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT,paused_at TEXT,paused_ms INTEGER NOT NULL DEFAULT 0,response_at TEXT,resolution_at TEXT,context_json TEXT NOT NULL DEFAULT '{}',dedup_key TEXT NOT NULL,UNIQUE(workspace_id,requester_id,dedup_key));
CREATE TABLE work_messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,author_id TEXT NOT NULL,visibility TEXT NOT NULL,body TEXT NOT NULL,source_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,work_id,source_key));
CREATE TABLE work_attachments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,visibility TEXT NOT NULL,blob_key TEXT NOT NULL,name TEXT NOT NULL,content_type TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE work_people(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,source TEXT NOT NULL,source_id TEXT NOT NULL,name TEXT NOT NULL,manager_id TEXT,active INTEGER NOT NULL DEFAULT 1,merged_into TEXT,revision INTEGER NOT NULL DEFAULT 1,observed_at TEXT NOT NULL,effective_at TEXT NOT NULL,UNIQUE(workspace_id,source,source_id));
CREATE TABLE work_assets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,serial TEXT NOT NULL,state TEXT NOT NULL,person_id TEXT,location TEXT,source TEXT NOT NULL,observed_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,serial));
CREATE TABLE work_custody(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,asset_id TEXT NOT NULL,actor_id TEXT NOT NULL,kind TEXT NOT NULL,person_id TEXT,evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE work_lifecycle(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,person_id TEXT NOT NULL,kind TEXT NOT NULL,effective_at TEXT NOT NULL,timezone TEXT NOT NULL,source TEXT NOT NULL,source_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,cancelled_at TEXT,UNIQUE(workspace_id,source,person_id,source_revision));
CREATE TABLE work_obligations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,lifecycle_id TEXT,kind TEXT NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,due_at TEXT NOT NULL,depends_on TEXT,state TEXT NOT NULL DEFAULT 'pending',owner_id TEXT,operation_id TEXT,last_error TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id,kind,target));
CREATE TABLE work_knowledge(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,scope TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,reviewer_id TEXT,reviewed_at TEXT,expires_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE work_erasure(workspace_id TEXT NOT NULL,person_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,person_id));
CREATE INDEX work_due ON work_obligations(state,due_at);

CREATE TABLE work_catalog(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,target TEXT NOT NULL,owner_id TEXT NOT NULL,requires_manager INTEGER NOT NULL DEFAULT 0,capacity INTEGER,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE work_fulfilments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,catalog_id TEXT NOT NULL,beneficiary_id TEXT NOT NULL,purpose TEXT NOT NULL,expires_at TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id,catalog_id));
CREATE TABLE work_delegations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,manager_id TEXT NOT NULL,delegate_id TEXT NOT NULL,starts_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE work_calendars(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,name TEXT NOT NULL,timezone TEXT NOT NULL,weekdays_json TEXT NOT NULL,start_hour INTEGER NOT NULL,end_hour INTEGER NOT NULL,holidays_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE work_commitments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,calendar_id TEXT NOT NULL,calendar_revision INTEGER NOT NULL,response_minutes INTEGER NOT NULL,resolution_minutes INTEGER NOT NULL,response_due_at TEXT NOT NULL,resolution_due_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id));

CREATE TABLE work_intake_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT,connection_id TEXT,source_message_id TEXT NOT NULL,sender TEXT,state TEXT NOT NULL,error TEXT,created_at TEXT NOT NULL,UNIQUE(workspace_id,connection_id,source_message_id));
CREATE TABLE work_sender_identities(workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,email TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(workspace_id,connection_id,email));
CREATE TABLE work_article_versions(workspace_id TEXT NOT NULL,article_id TEXT NOT NULL,revision INTEGER NOT NULL,content_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,article_id,revision));

-- Immutable hash of the complete accepted create payload; live work edits do not redefine retries.
-- Legacy rows remain NULL: their original mutable context cannot be reconstructed safely.
ALTER TABLE work_records ADD COLUMN request_hash TEXT;

-- Durable corrections retain the original execution identities and exact request.
CREATE TABLE work_fulfilment_amendments (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, work_id TEXT NOT NULL,
 fulfilment_id TEXT NOT NULL, event_key TEXT NOT NULL, requester_id TEXT NOT NULL,
 request_json TEXT NOT NULL, prior_json TEXT NOT NULL, state TEXT NOT NULL,
 reason TEXT, owner_id TEXT NOT NULL, step_json TEXT, actor_id TEXT,
 obligation_id TEXT, old_operation_id TEXT, old_operation_revision INTEGER,
 result_json TEXT, created_at TEXT NOT NULL,
 UNIQUE(workspace_id,work_id,event_key)
);
CREATE UNIQUE INDEX work_amend_prepared ON work_fulfilment_amendments(workspace_id,work_id) WHERE state='prepared';
CREATE TABLE work_fulfilment_removals (
 workspace_id TEXT NOT NULL, obligation_id TEXT NOT NULL, amendment_id TEXT NOT NULL,
 step_json TEXT NOT NULL, operation_id TEXT, plan_id TEXT,
 PRIMARY KEY(workspace_id,obligation_id), UNIQUE(workspace_id,operation_id)
);

CREATE TABLE execution_grants(id TEXT NOT NULL,workspace_id TEXT NOT NULL,version INTEGER NOT NULL,issuer_id TEXT NOT NULL,principal_id TEXT NOT NULL,parent_id TEXT,parent_version INTEGER,action TEXT NOT NULL,action_version INTEGER NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,connection_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,max_uses INTEGER NOT NULL CHECK(max_uses>0),conditions_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id,version));
CREATE TABLE execution_grant_revocations(workspace_id TEXT NOT NULL,grant_id TEXT NOT NULL,version INTEGER NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,grant_id,version));
CREATE TABLE execution_plans(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,work_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,actor_id TEXT NOT NULL,steps_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'proposed',idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE execution_decisions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,plan_id TEXT NOT NULL,operation_id TEXT,actor_id TEXT NOT NULL,grant_id TEXT,grant_version INTEGER,allowed INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE execution_operations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,plan_id TEXT NOT NULL,step_json TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,fence INTEGER NOT NULL DEFAULT 0,resource TEXT NOT NULL,actor_id TEXT NOT NULL,cancel_requested INTEGER NOT NULL DEFAULT 0,lease_until TEXT,due_at TEXT,parent_id TEXT,created_at TEXT NOT NULL,UNIQUE(plan_id,parent_id,resource));
CREATE TABLE execution_fences(workspace_id TEXT NOT NULL,resource TEXT NOT NULL,operation_id TEXT NOT NULL,fence INTEGER NOT NULL,PRIMARY KEY(workspace_id,resource));
CREATE TABLE execution_attempts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,fence INTEGER NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,elapsed_ms INTEGER,charge_status TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE execution_receipts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,attempt_id TEXT NOT NULL,state TEXT NOT NULL,provider_status INTEGER,created_at TEXT NOT NULL);
CREATE TABLE execution_verifications(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,operation_id TEXT NOT NULL,verifier_version INTEGER NOT NULL,action_version INTEGER NOT NULL,target TEXT NOT NULL,beneficiary_id TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE INDEX execution_due ON execution_operations(state,due_at);
CREATE TRIGGER execution_grants_immutable BEFORE UPDATE ON execution_grants BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
CREATE TRIGGER execution_decisions_immutable BEFORE UPDATE ON execution_decisions BEGIN SELECT RAISE(ABORT,'immutable decision'); END;

ALTER TABLE execution_plans ADD COLUMN context_type TEXT NOT NULL DEFAULT 'work';
ALTER TABLE execution_plans ADD COLUMN context_snapshot_json TEXT NOT NULL DEFAULT '{}';
CREATE TRIGGER execution_grants_no_delete BEFORE DELETE ON execution_grants BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
CREATE TRIGGER execution_decisions_no_delete BEFORE DELETE ON execution_decisions BEGIN SELECT RAISE(ABORT,'immutable decision'); END;

CREATE TABLE execution_erasure_permits(workspace_id TEXT NOT NULL,record_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,record_id));
DROP TRIGGER IF EXISTS execution_grants_no_delete;
CREATE TRIGGER execution_grants_no_delete BEFORE DELETE ON execution_grants WHEN NOT EXISTS(SELECT 1 FROM execution_erasure_permits WHERE workspace_id=OLD.workspace_id AND record_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
DROP TRIGGER IF EXISTS execution_decisions_no_delete;
CREATE TRIGGER execution_decisions_no_delete BEFORE DELETE ON execution_decisions WHEN NOT EXISTS(SELECT 1 FROM execution_erasure_permits WHERE workspace_id=OLD.workspace_id AND record_id=OLD.id) BEGIN SELECT RAISE(ABORT,'immutable decision'); END;

-- Additive repair for local databases that applied an earlier 0200/0201 revision.
CREATE TRIGGER IF NOT EXISTS execution_grants_immutable BEFORE UPDATE ON execution_grants BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
CREATE TRIGGER IF NOT EXISTS execution_decisions_immutable BEFORE UPDATE ON execution_decisions BEGIN SELECT RAISE(ABORT,'immutable decision'); END;
ALTER TABLE execution_grants ADD COLUMN connection_revision INTEGER NOT NULL DEFAULT 0;
-- Existing grants deliberately retain 0, requiring explicit reissue against current provider custody.

CREATE TABLE execution_subject_mappings(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_revision INTEGER NOT NULL,local_user_id TEXT NOT NULL,provider_subject TEXT NOT NULL,revision INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,observed_at TEXT NOT NULL,reviewed_by TEXT NOT NULL,UNIQUE(workspace_id,connection_id,local_user_id));
ALTER TABLE execution_grants ADD COLUMN local_beneficiary_id TEXT;
ALTER TABLE execution_grants ADD COLUMN mapping_id TEXT;
ALTER TABLE execution_grants ADD COLUMN mapping_revision INTEGER;

CREATE TABLE svc_records (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, kind TEXT NOT NULL,
 owner_id TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'operators',
 participants_json TEXT NOT NULL DEFAULT '[]', data_json TEXT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX svc_records_scope ON svc_records(workspace_id,kind,updated_at);
CREATE TABLE svc_events (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, record_id TEXT NOT NULL,
 actor_id TEXT NOT NULL, kind TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX svc_events_record ON svc_events(workspace_id,record_id,created_at);
CREATE TABLE svc_receipts (
 workspace_id TEXT NOT NULL, source_id TEXT NOT NULL, external_id TEXT NOT NULL,
 digest TEXT NOT NULL, received_at TEXT NOT NULL, PRIMARY KEY(workspace_id,source_id,external_id)
);
CREATE TABLE svc_outbox (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, record_id TEXT NOT NULL,
 recipient_id TEXT NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0,
 next_at TEXT NOT NULL, error TEXT, provider_ref TEXT,
