);
CREATE TABLE svc_commands (
 workspace_id TEXT NOT NULL, record_id TEXT NOT NULL, command_key TEXT NOT NULL,
 result_json TEXT NOT NULL, PRIMARY KEY(workspace_id,record_id,command_key)
);
CREATE TABLE svc_change_locks(workspace_id TEXT NOT NULL,service_id TEXT NOT NULL,change_id TEXT NOT NULL,PRIMARY KEY(workspace_id,service_id));
CREATE TRIGGER svc_events_immutable BEFORE UPDATE ON svc_events BEGIN SELECT RAISE(ABORT,'immutable service event'); END;
CREATE UNIQUE INDEX svc_monitor_incident ON svc_records(workspace_id,json_extract(data_json,'$.monitorEventKey')) WHERE kind='incident' AND json_extract(data_json,'$.monitorEventKey') IS NOT NULL;
ALTER TABLE svc_outbox ADD COLUMN connection_id TEXT;

CREATE TABLE intelligence_commitments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,owner_id TEXT NOT NULL,participants_json TEXT NOT NULL,sensitivity TEXT NOT NULL,data_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,due_at TEXT NOT NULL,lease_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX intelligence_due ON intelligence_commitments(due_at,lease_until);
CREATE TABLE intelligence_versions(commitment_id TEXT NOT NULL,revision INTEGER NOT NULL,workspace_id TEXT NOT NULL,data_json TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(commitment_id,revision));
CREATE TABLE intelligence_observations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,revision INTEGER NOT NULL,spec_id TEXT NOT NULL,cohort_json TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT NOT NULL,observed_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX intelligence_observation_scope ON intelligence_observations(workspace_id,commitment_id,created_at);
CREATE TABLE intelligence_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,source_id TEXT NOT NULL,event_id TEXT NOT NULL,source_revision TEXT NOT NULL,fingerprint TEXT NOT NULL,payload_json TEXT NOT NULL,observed_at TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,source_id,event_id));
CREATE TABLE intelligence_budgets(workspace_id TEXT PRIMARY KEY,limit_usd REAL NOT NULL,spent_usd REAL NOT NULL DEFAULT 0,reserved_usd REAL NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE intelligence_attempts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,commitment_id TEXT,run_id TEXT,kind TEXT NOT NULL,provider TEXT,model TEXT,connection_revision INTEGER,state TEXT NOT NULL,reserved_usd REAL NOT NULL DEFAULT 0,cost_usd REAL,charge_status TEXT NOT NULL,usage_json TEXT,elapsed_ms INTEGER,error_code TEXT,request_id TEXT,created_at TEXT NOT NULL,finished_at TEXT);
CREATE TABLE intelligence_research(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,actor_id TEXT NOT NULL,connection_id TEXT NOT NULL,question TEXT NOT NULL,state TEXT NOT NULL,round INTEGER NOT NULL DEFAULT 0,data_json TEXT NOT NULL,lease_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE intelligence_protocol_runs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,input_json TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE intelligence_capabilities(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,research_id TEXT NOT NULL,version INTEGER NOT NULL,data_json TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE intelligence_reuse(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,capability_id TEXT NOT NULL,commitment_id TEXT NOT NULL,state TEXT NOT NULL,data_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE intelligence_simplifications(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,change_id TEXT NOT NULL,data_json TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE intelligence_engineering_grants(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,version INTEGER NOT NULL,owner_id TEXT NOT NULL,token_hash TEXT NOT NULL,config_json TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE intelligence_engineering_jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,commitment_id TEXT NOT NULL,research_id TEXT,grant_id TEXT,grant_version INTEGER,state TEXT NOT NULL,spec_json TEXT NOT NULL,claim_token_hash TEXT,lease_until TEXT,receipt_json TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE intelligence_intake(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,actor_id TEXT NOT NULL,fingerprint TEXT NOT NULL,state TEXT NOT NULL,data_json TEXT NOT NULL,lease_until TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,work_id,fingerprint));
CREATE TABLE intelligence_restore_records(workspace_id TEXT NOT NULL,source_id TEXT NOT NULL,source_key TEXT NOT NULL,table_name TEXT NOT NULL,record_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,source_id,source_key));

-- Consolidate early local queue into Work atomic event outbox; retain applied history.
INSERT OR IGNORE INTO work_intake_events(id,workspace_id,work_id,connection_id,source_message_id,sender,state,created_at)
SELECT id,workspace_id,work_id,'','restored-intelligence:'||fingerprint,actor_id,'pending',created_at FROM intelligence_intake WHERE state NOT IN ('proposed','interpreted');
DROP TABLE intelligence_intake;

CREATE TABLE intelligence_investigations (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, work_id TEXT NOT NULL,
 requester_id TEXT NOT NULL, service_id TEXT NOT NULL, service_revision INTEGER NOT NULL,
 owner_id TEXT NOT NULL, incident_id TEXT, commitment_id TEXT, commitment_revision INTEGER,
 research_id TEXT, state TEXT NOT NULL, error_code TEXT, reported_key TEXT,
 lease_until TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(workspace_id,work_id)
);
CREATE INDEX intelligence_investigations_due ON intelligence_investigations(workspace_id,state);

-- Earlier probe admission incorrectly promoted provenance exceptions to failures.
-- Preserve the diagnostic/attempt record but withdraw its claimed observation time.
UPDATE intelligence_observations SET state='uncertain',observed_at=''
WHERE state='failed' AND json_extract(evidence_json,'$.error') IS NOT NULL;

CREATE TABLE intelligence_pending_fulfilments (
 id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, work_id TEXT NOT NULL, catalog_id TEXT NOT NULL,
 requester_id TEXT NOT NULL, work_revision INTEGER NOT NULL, input_json TEXT NOT NULL,
 state TEXT NOT NULL, error_code TEXT, lease_until TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(workspace_id,work_id,catalog_id)
);

CREATE TABLE adoption_exports(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,checkpoint INTEGER NOT NULL DEFAULT 0,manifest_json TEXT NOT NULL DEFAULT '{}',error TEXT,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE adoption_snapshot(export_id TEXT NOT NULL,workspace_id TEXT NOT NULL,seq INTEGER PRIMARY KEY AUTOINCREMENT,table_name TEXT NOT NULL,source_key TEXT NOT NULL,row_json TEXT NOT NULL);
CREATE INDEX adoption_snapshot_page ON adoption_snapshot(export_id,seq);
CREATE TABLE adoption_chunks(workspace_id TEXT NOT NULL,run_id TEXT NOT NULL,ordinal INTEGER NOT NULL,kind TEXT NOT NULL,object_key TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,metadata_json TEXT NOT NULL,PRIMARY KEY(workspace_id,run_id,ordinal));
CREATE TABLE adoption_imports(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,source_id TEXT NOT NULL,state TEXT NOT NULL,manifest_json TEXT NOT NULL,report_json TEXT NOT NULL DEFAULT '{}',checkpoint INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE adoption_history(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,import_id TEXT NOT NULL,source_id TEXT NOT NULL,table_name TEXT NOT NULL,source_key TEXT NOT NULL,revision TEXT NOT NULL,row_json TEXT NOT NULL,state TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL,UNIQUE(workspace_id,source_id,table_name,source_key,revision));
CREATE INDEX adoption_history_import ON adoption_history(workspace_id,import_id,table_name);
CREATE TABLE adoption_holds(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,import_id TEXT,state TEXT NOT NULL,reason TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,released_at TEXT);
CREATE TABLE adoption_reconciliations(workspace_id TEXT NOT NULL,hold_id TEXT NOT NULL,history_id TEXT NOT NULL,actor_id TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,hold_id,history_id));
CREATE TABLE adoption_tombstones(workspace_id TEXT NOT NULL,identity_hash TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,identity_hash));
CREATE TABLE adoption_retention(workspace_id TEXT PRIMARY KEY,archive_days INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE adoption_deletions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,object_key TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(workspace_id,object_key));
CREATE TABLE adoption_sources(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,provider TEXT NOT NULL,source_workspace INTEGER NOT NULL,state TEXT NOT NULL,checkpoint TEXT NOT NULL,page INTEGER NOT NULL DEFAULT 1,last_seen_at TEXT,revision INTEGER NOT NULL DEFAULT 1,error TEXT,UNIQUE(workspace_id,connection_id,source_workspace));
CREATE TABLE adoption_source_records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,source_id TEXT NOT NULL,external_id TEXT NOT NULL,revision TEXT NOT NULL,digest TEXT NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL,received_at TEXT NOT NULL,UNIQUE(workspace_id,source_id,external_id,revision));
CREATE TABLE adoption_ownership(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,resource TEXT NOT NULL,action TEXT NOT NULL,source_id TEXT,executor TEXT NOT NULL,state TEXT NOT NULL,fence INTEGER NOT NULL,source_revision TEXT,approval_id TEXT,approval_revision TEXT,approval_expires TEXT,feed_expires TEXT,cutover_checkpoint TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,resource,action));
CREATE TABLE adoption_writebacks(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,source_id TEXT NOT NULL,external_id TEXT NOT NULL,operation_id TEXT NOT NULL,marker TEXT NOT NULL,state TEXT NOT NULL,provider_ref TEXT,created_at TEXT NOT NULL,UNIQUE(workspace_id,source_id,operation_id));

ALTER TABLE adoption_erasure_jobs ADD COLUMN identity_ciphertext TEXT;
ALTER TABLE adoption_erasure_jobs ADD COLUMN actor_id TEXT;
ALTER TABLE adoption_erasure_jobs ADD COLUMN error_code TEXT;
ALTER TABLE adoption_erasure_jobs ADD COLUMN updated_at TEXT;

-- Preserve the import-to-erasure obligation even after a profile is redacted.
CREATE TABLE adoption_import_erasures (
 workspace_id TEXT NOT NULL, import_id TEXT NOT NULL, job_id TEXT NOT NULL,
 PRIMARY KEY(workspace_id,import_id,job_id)
);

-- Install only after 0500 creates adoption_tombstones. Keep the 0070 receipt
-- table and its data intact on both fresh installs and retained-history upgrades.
-- Previously applied 0070 versions already installed these guards; replace them
-- atomically within the migration transaction without rewriting migration history.
DROP TRIGGER IF EXISTS platform_erasure_authority;
DROP TRIGGER IF EXISTS platform_erased_membership_insert;
DROP TRIGGER IF EXISTS platform_erased_membership_update;
CREATE TRIGGER platform_erasure_authority BEFORE INSERT ON platform_identity_erasures BEGIN
 SELECT RAISE(ABORT,'platform_owner_required') WHERE NOT EXISTS (
  SELECT 1 FROM memberships m,json_each(m.roles_json) r
  WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_id AND m.active=1 AND r.value='owner'
 );
 SELECT RAISE(ABORT,'platform_tombstone_required') WHERE NOT EXISTS (
  SELECT 1 FROM adoption_tombstones WHERE workspace_id=NEW.workspace_id AND identity_hash=NEW.identity_hash
 );
 SELECT RAISE(ABORT,'platform_another_owner_required') WHERE NEW.user_id IS NOT NULL AND EXISTS (
  SELECT 1 FROM memberships m,json_each(m.roles_json) r WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.user_id AND m.active=1 AND r.value='owner'
 ) AND NOT EXISTS (
  SELECT 1 FROM memberships m,json_each(m.roles_json) r WHERE m.workspace_id=NEW.workspace_id AND m.user_id<>NEW.user_id AND m.active=1 AND r.value='owner'
 );
END;
